@app.route("/api/translate", methods=["POST"])
def api_translate():
    """
    Translation endpoint used by the dashboard to translate itinerary and
    page text on demand. Supports both single string and list payloads.
    """
    data = request.get_json(silent=True) or {}
    target_lang = (data.get("target_lang") or "").strip()
    texts = data.get("texts")
    text = (data.get("text") or "").strip()

    if (not text and not texts) or not target_lang:
        return jsonify({"error": "Missing text(s) or target language."}), 400

    translator = GoogleTranslator(source="auto", target=target_lang)

    def translate_with_chunking(value: str, max_chars: int = 4500) -> str:
        """
        deep-translator raises errors for very long strings. Split long text
        into smaller chunks and translate each chunk safely.
        """
        cleaned = (value or "").strip()
        if not cleaned:
            return ""
        if len(cleaned) <= max_chars:
            return translator.translate(cleaned)

        chunks = []
        start = 0
        while start < len(cleaned):
            end = min(start + max_chars, len(cleaned))
            if end < len(cleaned):
                split_at = cleaned.rfind(" ", start, end)
                if split_at > start:
                    end = split_at
            chunks.append(cleaned[start:end].strip())
            start = end

        translated_chunks = [translator.translate(chunk) for chunk in chunks if chunk]
        return " ".join(translated_chunks)

    if isinstance(texts, list):
        translated_items = []
        try:
            for item in texts:
                item_text = (item or "").strip()
                translated_items.append(translate_with_chunking(item_text) if item_text else "")
        except Exception:
            return jsonify({"error": "Translation failed. Please try again."}), 500
        return jsonify({"translated_texts": translated_items})

    try:
        translated = translate_with_chunking(text)
    except Exception:
        return jsonify({"error": "Translation failed. Please try again."}), 500

    return jsonify({"translated_text": translated})


@sitemapper.include() # Include the route in the sitemap
@app.route("/login", methods=["GET", "POST"])
def login():
    """
    Renders the login.html template.

    Returns:
        The rendered login.html template.
    """
    if request.method == "POST":
        email = request.form.get("email")
        password = request.form.get("password")
        user = User.query.filter_by(email=email).first()
        if user and user.check_password(password):
            session["user_id"] = user.id
            session["user_name"] = user.name
            session["user_email"] = user.email
            flash("Login successful.", "success")
            print(session["user_email"])
            return redirect(url_for("index"))

        else:
            flash("Wrong email or password. Please try again or register now.", "danger")
            return redirect(url_for("login"))
    else:
        return render_template("login.html")

