<!-- This script tag includes the markdown-it library from the specified CDN. -->
<script src="https://cdn.jsdelivr.net/npm/markdown-it@11.0.1/dist/markdown-it.min.js"></script>

<!-- This script creates a Markdown parser, converts the Markdown text to HTML, and inserts the converted HTML into the document. The Markdown text is obtained from an element with the ID "markdown-content". -->
<script>
  const md = window.markdownit();
  const markdownElement = document.getElementById("markdown-content");
  const originalMarkdown = markdownElement ? markdownElement.textContent : "";
  const renderMarkdown = (text) => {
    if (markdownElement) {
      markdownElement.innerHTML = md.render(text);
    }
  };

  renderMarkdown(originalMarkdown);

  const translateRun = document.getElementById("translate-run");
  const languageSelect = document.getElementById("language-select");
  const translateStatus = document.getElementById("translate-status");
  const translateHint = document.getElementById("translate-hint");

  const translateTargets = [];
  translateTargets.push({ type: "markdown", original: originalMarkdown });

  const translatableElements = Array.from(document.querySelectorAll("[data-translate]"));
  translatableElements.forEach((el) => {
    const original = (el.textContent || "").trim();
    el.dataset.original = original;
    translateTargets.push({ type: "element", el, original });
  });

  const languageOptions = languageSelect
    ? Array.from(languageSelect.options)
        .filter((opt) => opt.value)
        .map((opt) => ({ value: opt.value, label: opt.textContent || opt.value, element: opt }))
    : [];

  let languageFilter = "";
  const applyLanguageFilter = (term) => {
    const value = (term || "").trim().toLowerCase();
    languageOptions.forEach((opt) => {
      const match = !value || opt.label.toLowerCase().includes(value) || opt.value.toLowerCase().includes(value);
      opt.element.hidden = !match;
    });
  };

  if (languageSelect) {
    const handleTranslate = async () => {
      const targetLang = languageSelect.value;
      if (!targetLang || translateTargets.length === 0) {
        alert("Please choose a valid language.");
        return;
      }

      if (translateStatus) {
        translateStatus.textContent = "Translating... please wait";
        translateStatus.style.display = "inline";
      }
      languageSelect.disabled = true;
      if (translateRun) {
        translateRun.disabled = true;
      }

      try {
        const response = await fetch("/api/translate", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ texts: translateTargets.map((t) => t.original), target_lang: targetLang }),
        });
        const payload = await response.json();
        if (!response.ok || !payload.translated_texts || payload.translated_texts.length !== translateTargets.length) {
          throw new Error(payload.error || "Translation failed. Please try again.");
        }

        payload.translated_texts.forEach((text, index) => {
          const target = translateTargets[index];
          if (target.type === "markdown") {
            renderMarkdown(text || originalMarkdown);
          } else if (target.el) {
            target.el.textContent = text;
          }
        });
      } catch (error) {
        alert(error.message || "Translation failed. Please try again.");
        languageSelect.value = "";
        renderMarkdown(originalMarkdown);
        translatableElements.forEach((el) => {
          el.textContent = el.dataset.original || el.textContent;
        });
      } finally {
        if (translateStatus) {
          translateStatus.style.display = "none";
          translateStatus.textContent = "Translating... please wait";
        }
        languageSelect.disabled = false;
        if (translateRun) {
          translateRun.disabled = false;
        }
      }
    };

    languageSelect.addEventListener("keydown", (e) => {
      const key = e.key;
      const isCharacter = key.length === 1 && !e.ctrlKey && !e.metaKey && !e.altKey;
      if (isCharacter) {
        languageFilter += key;
        applyLanguageFilter(languageFilter);
      } else if (key === "Backspace") {
        languageFilter = languageFilter.slice(0, -1);
        applyLanguageFilter(languageFilter);
      } else if (key === "Escape") {
        languageFilter = "";
        applyLanguageFilter(languageFilter);
      } else if (key === "Enter") {
        // Do not auto-translate on Enter; only the button triggers translation.
        e.preventDefault();
      }
    });
    if (translateRun) {
      translateRun.addEventListener("click", handleTranslate);
    }
  }

  const downloadButton = document.getElementById('download');
  if (downloadButton) {
    downloadButton.addEventListener('click', function() {
      if (!markdownElement || !markdownElement.innerHTML.trim()) {
        alert('Itinerary is not available yet. Please generate it first.');
        return;
      }

      const exportNode = document.createElement('section');
      exportNode.style.padding = '24px';
      exportNode.style.background = '#ffffff';
      exportNode.style.color = '#111827';
      exportNode.style.fontFamily = 'Arial, sans-serif';
      exportNode.style.lineHeight = '1.6';

      const now = new Date();
      const dateString = now.toLocaleDateString();
      exportNode.innerHTML =
        '<h1 style="margin:0 0 6px 0; font-size:24px;">Travel Itinerary</h1>' +
        '<p style="margin:0 0 16px 0; color:#4b5563;">Generated on ' + dateString + '</p>' +
        markdownElement.innerHTML;

      const opt = {
        margin: 0.5,
        filename: 'itinerary.pdf',
        image: { type: 'jpeg', quality: 0.98 },
        html2canvas: { scale: 1.4, useCORS: true },
        jsPDF: { unit: 'in', format: 'letter', orientation: 'portrait' },
      };

      html2pdf().set(opt).from(exportNode).save();
    });
  }

</script>
